import React, {useEffect, useState} from 'react';
import HeaderCM from '../../components/Header/HeaderCM';
import {
  Keyboard,
  TouchableOpacity,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import {useTranslation} from 'react-i18next';

import RenderTabView from './component/tab-view';
import {Icon, Input} from '@ui-kitten/components';
import BottomSheetCM from '../../components/BottomSheet';
import ModalFilter from './component/modal-filter';
import {styles} from './styles';
import {Color} from '../../../constants';
import {useReceiptZustandStore} from './store/myReceiptZustandStore';
import {useReceiptServices} from '../../../hooks/apiHooks/useAPI';
import {
  listPayment,
  listRequestStatus,
  listStatusReceipt,
} from './component/modal-filter/helper';
import useDebounce from '../../../hooks/useDebounce';

const MyReceiptScreen = () => {
  const {t} = useTranslation();
  const [value, setValue] = useState('');
  const valueTextSaerch = useDebounce(value, 300);
  const [visibleFilter, setVisibleFilter] = useState(false);
  const {
    groupListReceipt,
    valueFilterSearch,
    sizePageReceipt,
    currentRequestStatus,
    groupToTalCountReceipt,
    groupPageReceipt,
    setGroupListReceipt,
    setGroupPageReceipt,
    setGroupToTalCountReceipt,
    setQueryFilterReceipt,
    setListTypeReceipt,
    listTypeReceipt,
  } = useReceiptZustandStore();
  const {rangeDay, paymentMethod, status, type, requestStatus} =
    valueFilterSearch;
  const ReceiptService = useReceiptServices();

  useEffect(() => {
    setGroupPageReceipt({});
    setQueryFilterReceipt(valueTextSaerch);
  }, [valueTextSaerch]);

  useEffect(() => {
    getListTypeReceipt();
  }, []);

  const getListTypeReceipt = async () => {
    try {
      const data = await ReceiptService.getReceiptTemplate();
      if (data) {
        setListTypeReceipt(
          data.map((d: any) => ({
            id: d.id,
            label: d.name,
            value: d.code,
          })),
        );
      }
    } catch (error) {}
  };
  const getDataReceipt = async (query?: string) => {
    try {
      const bodySearch: any = {
        q: query?.trim(),
        terms: {flowStatus: currentRequestStatus},
      };
      if (paymentMethod) {
        bodySearch.terms.category = paymentMethod.map(
          item => listPayment[item.row].label,
        );
      }
      if (status) {
        bodySearch.terms.status = status.map(
          item => listStatusReceipt[item.row].value,
        );
      }

      if (type) {
        bodySearch.terms.type = type.map(
          item => listTypeReceipt[item.row].value,
        );
      }

      if (requestStatus) {
        bodySearch.terms.requestStatus = requestStatus.map(
          item => listRequestStatus[item.row].value,
        );
      }

      if (rangeDay?.startDate) {
        bodySearch.terms.dateStart = rangeDay.startDate.toISOString();
      }
      if (rangeDay?.endDate) {
        bodySearch.terms.dateEnd = rangeDay.endDate.toISOString();
      }

      const res = await ReceiptService.getReceipt(
        0,
        sizePageReceipt,
        bodySearch,
      );
      if (res?.data) {
        setGroupListReceipt({
          ...groupListReceipt,
          [currentRequestStatus]: res.data,
        });
        setGroupToTalCountReceipt({
          ...groupToTalCountReceipt,
          [currentRequestStatus]: res.totalData,
        });
        setGroupPageReceipt({
          ...groupPageReceipt,
          [currentRequestStatus]: 0,
        });
      }
    } catch (error) {}
  };

  const handleSubmitFilter = () => {
    setGroupPageReceipt({});
    getDataReceipt();
    setVisibleFilter(false);
  };

  const checkIsFilter = () => {
    return (
      valueFilterSearch.rangeDay?.endDate ||
      valueFilterSearch.rangeDay?.startDate ||
      paymentMethod?.length ||
      status?.length ||
      type?.length
    );
  };

  return (
    <TouchableWithoutFeedback onPress={() => Keyboard.dismiss()}>
      <View style={styles.ctn}>
        <HeaderCM
          title="Biên lai của tôi"
          useLinearGradient={false}
          style={{backgroundColor: Color.BgPrimary}}
          contentStyle={{backgroundColor: Color.BgPrimary}}
          // renderContentRight={() => (
          //   <TouchableOpacity onPress={() => false}>
          //     <IconMyReceiptTopRight width={20} height={20} />
          //   </TouchableOpacity>
          // )}
        />
        <View style={styles.wrapInputSearch}>
          <Input
            allowFontScaling={false}
            style={styles.inputSearch}
            textStyle={{color: Color.Black}}
            placeholderTextColor={'#9FB0C7'}
            placeholder={t('CM.search')}
            value={value}
            status="basic"
            onChangeText={setValue}
            accessoryLeft={
              <TouchableOpacity onPress={() => false}>
                <Icon fill={'#9FB0C7'} name="search" />
              </TouchableOpacity>
            }
            accessoryRight={
              value ? (
                <TouchableOpacity onPress={() => setValue('')}>
                  <Icon name="close-outline" fill={Color.Black} />
                </TouchableOpacity>
              ) : undefined
            }
          />
          <TouchableOpacity
            onPress={() => setVisibleFilter(true)}
            style={styles.wrapFilterIcon}>
            <Icon
              fill={Color.White}
              name={checkIsFilter() ? 'funnel' : 'funnel-outline'}
              width={25}
              height={25}
            />
          </TouchableOpacity>
        </View>
        <BottomSheetCM
          title={t('CM.filter')}
          onClose={() => setVisibleFilter(false)}
          isVisible={visibleFilter}
          renderContent={
            <ModalFilter
              handleSubmitFilter={handleSubmitFilter}
              onClose={() => setVisibleFilter(false)}
            />
          }
        />
        <RenderTabView />
      </View>
    </TouchableWithoutFeedback>
  );
};

export default MyReceiptScreen;
