import {
  ActivityIndicator,
  FlatList,
  TouchableOpacity,
  View,
} from 'react-native';
import {useCallback, useEffect, useState} from 'react';
import {Color, Font, NavigationName} from '../../../../../../../constants';
import Svg, {Ellipse, Line} from 'react-native-svg';
import {styles} from './styles';
import Toast from 'react-native-toast-message';
import {t} from 'i18next';
import {
  useFocusEffect,
  useNavigation,
  useRoute,
} from '@react-navigation/native';
import LoadingMore from '../../../../../../components/LoadingMore';
import TextCM from '../../../../../../components/Text';
import {useReceiptServices} from '../../../../../../../hooks/apiHooks/useAPI';
import {IReceiptItem} from '../../../../../../../model/interface/receipt.interface';
import {DateUtils} from '../../../../../../../utils';
import {useReceiptZustandStore} from '../../../../store/myReceiptZustandStore';
import {
  listPayment,
  listRequestStatus,
  listStatusReceipt,
} from '../../../modal-filter/helper';
import {TYPE_REQUEST_FLOW} from '../../../../../../../model/type/status';
import {useAccountInfoServices} from '../../../../../../../hooks/apiHooks/useAccountInfoServices';

type Props = {
  flowStatus: TYPE_REQUEST_FLOW;
};

const ListReceipt = ({flowStatus}: Props) => {
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const isReload = route?.params?.isReload || false;
  const {
    groupListReceipt,
    groupPageReceipt,
    groupToTalCountReceipt,
    sizePageReceipt,
    queryFilterReceipt,
    valueFilterSearch,
    setGroupListReceipt,
    setGroupPageReceipt,
    setGroupToTalCountReceipt,
    currentRequestStatus,
    listTypeReceipt,
  } = useReceiptZustandStore();
  const ReceiptService = useReceiptServices();
  const [isRefreshing, setIsFreshing] = useState(false);
  const [isLoadMore, setIsLoadMore] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [typereceipt] = useState([
    {type: 'c', name: 'Biên lai thu tiền'},
    {type: 'r', name: 'Biên lai kết chuyển'},
  ]);
  const [currentTypeReceipt, setCurrentTypeReceipt] = useState<'c' | 'r'>('c');
  const [widthOfCard, setWidthOfCard] = useState(0);
  const AccountService = useAccountInfoServices();

  const {rangeDay, paymentMethod, status, type, requestStatus} =
    valueFilterSearch;

  const getDataReceipt = async (page: number, isLoadMore: boolean) => {
    try {
      if (!isLoadMore) {
        setIsLoading(true);
      }
      const bodySearch: any = {
        terms: {flowStatus},
        q: queryFilterReceipt,
      };

      if (paymentMethod) {
        bodySearch.terms.category = paymentMethod.map(
          item => listPayment[item.row].label,
        );
      }
      if (status) {
        bodySearch.terms.status = status.map(
          item => listStatusReceipt[item.row].value,
        );
      }

      if (type) {
        bodySearch.terms.typeDoc = type.map(
          item => listTypeReceipt[item.row].value,
        );
      }

      if (requestStatus) {
        bodySearch.terms.requestStatus = requestStatus.map(
          item => listRequestStatus[item.row].value,
        );
      }

      if (rangeDay?.startDate) {
        bodySearch.terms.dateStart = rangeDay.startDate.toISOString();
      }
      if (rangeDay?.endDate) {
        bodySearch.terms.dateEnd = rangeDay.endDate.toISOString();
      }
      const res = await ReceiptService.getReceipt(
        page,
        sizePageReceipt,
        bodySearch,
      );
      if (res?.data) {
        if (page === 0) {
          setGroupListReceipt({
            ...groupListReceipt,
            [flowStatus]: res.data,
          });
          setGroupToTalCountReceipt({
            ...groupToTalCountReceipt,
            [flowStatus]: res.totalData,
          });
        } else {
          const newListReceipt = {
            ...groupListReceipt,
            [flowStatus]: [
              ...(groupListReceipt[flowStatus] || []),
              ...res.data,
            ],
          };
          setGroupListReceipt(newListReceipt);
        }
        setGroupPageReceipt({
          ...groupPageReceipt,
          [flowStatus]: page,
        });
      }
    } catch (error) {
    } finally {
      setIsLoading(false);
    }
  };

  useFocusEffect(
    useCallback(() => {
      if (isReload) {
        getDataReceipt(0, false);
      }
    }, []),
  );

  useEffect(() => {
    if (currentRequestStatus === flowStatus) {
      // AccountService.loginMiniApp();
      getDataReceipt(0, false);
    }
  }, [currentRequestStatus, queryFilterReceipt]);

  const onRefresh = async () => {
    try {
      setIsFreshing(true);
      await getDataReceipt(0, false);
      setGroupPageReceipt({
        ...groupPageReceipt,
        [flowStatus]: 0,
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    } finally {
      setIsFreshing(false);
    }
  };

  const navigateToDetailReceiptScreen = (id: string) => {
    navigation.navigate(NavigationName.DetailReceiptScreen, {id});
  };

  const handleChangeTypeReceipt = (type: 'c' | 'r') => {
    setCurrentTypeReceipt(type);
  };

  const handleLoadMore = async () => {
    try {
      if (
        groupListReceipt[flowStatus] &&
        groupListReceipt[flowStatus].length <
          (groupToTalCountReceipt[flowStatus] || 0)
      ) {
        await getDataReceipt((groupPageReceipt[flowStatus] || 0) + 1, true);
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    } finally {
    }
  };

  const handleGenerateNumber = async (id: string) => {
    const dataResp = await ReceiptService.reGenerateNumberReceipt(id);
    if (dataResp) {
      Toast.show({
        type: 'success',
        text1: t('CM.noti'),
        text2: t('CM.success'),
      });
    } else {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    }
  };

  const DashLine = () => {
    return (
      <Svg height="10" width={'100%'} style={styles.dashLine}>
        <Ellipse cx="0" cy="5" rx="10" ry="4" fill="#f9fafe" />
        <Ellipse cx={'100%'} cy="5" rx="10" ry="4" fill="#f9fafe" />
        <Line
          x1="20"
          y1="5"
          x2={widthOfCard - 20}
          y2="5"
          stroke="#cbcbcb"
          strokeWidth="1"
          strokeDasharray="8.8"
        />
      </Svg>
    );
  };

  const renderReceiptItem = (receipt: IReceiptItem) => {
    const data = receipt.data;
    return (
      <TouchableOpacity
        onPress={() => navigateToDetailReceiptScreen(data.id)}
        style={styles.container}>
        <View
          onLayout={event => {
            const {width} = event.nativeEvent.layout;
            setWidthOfCard(width);
          }}
          style={[
            styles.card,
            styles.radiusTop,
            styles.shadowTop,
            styles.shadowLeft,
            styles.shadowRight,
          ]}>
          <View style={styles.header}>
            <View style={{flex: 1, columnGap: 8}}>
              <TextCM style={styles.title}>{data.name || '---'}</TextCM>
              <TextCM style={styles.idNumber}>{data.caseCode || '---'}</TextCM>
            </View>
            {data.status === 'error_receipt' && (
              <TouchableOpacity
                onPress={() => handleGenerateNumber(data.id)}
                style={{
                  paddingHorizontal: 6,
                  paddingVertical: 4,
                  backgroundColor: Color.BgPrimary,
                  borderRadius: 4,
                }}>
                <TextCM
                  style={{color: Color.White, fontFamily: Font.InterMedium500}}>
                  Cấp số
                </TextCM>
              </TouchableOpacity>
            )}
          </View>
        </View>

        <DashLine />

        <View
          style={[
            styles.card,
            styles.radiusBot,
            styles.shadowBottom,
            styles.shadowLeft,
            styles.shadowRight,
          ]}>
          <View style={styles.receiptTypeSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.receiptTypeLabel}>Loại biên lai</TextCM>
            </View>
            <View style={{flex: 1}}>
              <TextCM style={styles.receiptTypeCode}>{data.type || '---'}</TextCM>
            </View>
          </View>

          <View style={styles.dateSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.dateLabel}>Ngày tạo</TextCM>
            </View>
            <TextCM style={styles.dateValue}>
              {DateUtils.convertDateToDDMMYYYY_H_M(data.createdDate) || '---'}
            </TextCM>
          </View>

          <View style={styles.statusSection}>
            <View style={styles.lableCardWrap}>
              <TextCM style={styles.statusLabel}>Trạng thái Biên lai</TextCM>
            </View>
            {data.status && renderStatus(data.status)}
          </View>
        </View>
      </TouchableOpacity>
    );
  };

  const renderStatus = (status: string) => {
    const statusProps = listStatusReceipt.find(
      (item: any) => item.value == status,
    );
    if (statusProps) {
      return (
        <View
          style={[styles.statusButton, {backgroundColor: statusProps.bgColor}]}>
          <TextCM style={[styles.statusButtonText, {color: statusProps.color}]}>
            {t(`BLDT.${statusProps.value}`)}
          </TextCM>
        </View>
      );
    }
    return (
      <View style={[styles.statusButton, {backgroundColor: '#F2ECFD'}]}>
        <TextCM style={[styles.statusButtonText, {color: '#7c3aed'}]}>
          {t(`BLDT.${status}`)}
        </TextCM>
      </View>
    );
  };

  const renderTypeReceipt = (item: any) => {
    return (
      <TouchableOpacity
        key={item.type}
        onPress={() => handleChangeTypeReceipt(item.type)}
        style={styles.containerTypereceipt}>
        {currentTypeReceipt === item.type ? (
          <View style={styles.typeReceiptSelected}>
            <View
              style={{
                width: 8,
                height: 8,
                backgroundColor: Color.White,
                borderRadius: 10,
              }}></View>
          </View>
        ) : (
          <View style={styles.typeReceiptDefault}></View>
        )}
        <TextCM
          style={[
            styles.textTypeReceipt,
            {
              color: currentTypeReceipt === item.type ? '#262D34' : '#667085',
            },
          ]}>
          {item.name}
        </TextCM>
      </TouchableOpacity>
    );
  };

  return (
    <View style={{flex: 1, backgroundColor: '#f9fafe'}}>
      <View style={{flexDirection: 'row', gap: 16, marginBottom: 10}}>
        {typereceipt.map((item: any) => renderTypeReceipt(item))}
      </View>

      {isLoading && (
        <ActivityIndicator
          style={{marginTop: 10}}
          color={Color.BgPrimary}
          size="large"
        />
      )}

      {groupListReceipt[flowStatus] && !isLoading && (
        <FlatList
          showsVerticalScrollIndicator={false}
          style={{flex: 1}}
          data={groupListReceipt[flowStatus]}
          keyExtractor={item => item?.data?.id}
          renderItem={({item}) => renderReceiptItem(item)}
          onEndReachedThreshold={0.5}
          onRefresh={onRefresh}
          refreshing={isRefreshing}
          onEndReached={handleLoadMore}
          ListEmptyComponent={() => (
            <View
              style={{
                alignItems: 'center',
                justifyContent: 'center',
                flex: 1,
              }}>
              <TextCM>{t('CM.emptyData')}</TextCM>
            </View>
          )}
          ListFooterComponent={() => isLoadMore && <LoadingMore />}
        />
      )}
    </View>
  );
};

export default ListReceipt;
