import {CalendarRange, IndexPath} from '@ui-kitten/components';
import {create} from 'zustand';
import {
  IReceiptItem,
  TypeReceipt,
} from '../../../../model/interface/receipt.interface';
import {TYPE_REQUEST_FLOW} from '../../../../model/type/status';

export type ValueFilterSearch = {
  rangeDay?: CalendarRange<Date>;
  paymentMethod?: IndexPath[];
  requestStatus?: IndexPath[];
  status?: IndexPath[];
  type?: IndexPath[];
};
type GroupedListReceipt = {[key in TYPE_REQUEST_FLOW]?: IReceiptItem[]};
type GroupedPageReceipt = {[key in TYPE_REQUEST_FLOW]?: number};
type GrouptTotalCountReceipt = {[key in TYPE_REQUEST_FLOW]?: number};

interface ZutandStore {
  valueFilterSearch: ValueFilterSearch;
  groupListReceipt: GroupedListReceipt;
  currentTypeReceipt: TypeReceipt;
  currentRequestStatus: TYPE_REQUEST_FLOW;
  groupPageReceipt: GroupedPageReceipt;
  groupToTalCountReceipt: GrouptTotalCountReceipt;
  listTypeReceipt: {label: string; value: string}[];
  sizePageReceipt: number;
  queryFilterReceipt: string;
  setValueFilterSearch: (valueFilterSearch: ValueFilterSearch) => void;
  setGroupListReceipt: (groupListReceipt: GroupedListReceipt) => void;
  setCurrentTypeReceipt: (currentTypeReceipt: 'c' | 'r') => void;
  setCurrentStatusRequestReceipt: (
    currentRequestStatus: TYPE_REQUEST_FLOW,
  ) => void;
  setGroupPageReceipt: (groupPageReceipt: GroupedPageReceipt) => void;
  setGroupToTalCountReceipt: (
    groupToTalCountReceipt: GrouptTotalCountReceipt,
  ) => void;
  setQueryFilterReceipt: (queryFilter: string) => void;
  setListTypeReceipt: (
    listTypeReceipt: {label: string; value: string}[],
  ) => void;
}

const initialReceiptState = {
  valueFilterSearch: {
    rangeDay: {startDate: undefined, endDate: undefined},
  },
  listTypeReceipt: [],
  groupListReceipt: {} as GroupedListReceipt,
  currentTypeReceipt: 'c' as TypeReceipt,
  currentRequestStatus: 'receipt_numbering' as TYPE_REQUEST_FLOW,
  groupPageReceipt: {} as GroupedPageReceipt,
  groupToTalCountReceipt: {} as GrouptTotalCountReceipt,
  sizePageReceipt: 10,
  queryFilterReceipt: '',
};

export const useReceiptZustandStore = create<ZutandStore>((set, get) => ({
  ...initialReceiptState,
  setValueFilterSearch: (valueFilterSearch: ValueFilterSearch) => {
    set({valueFilterSearch});
  },
  setGroupListReceipt: (groupListReceipt: GroupedListReceipt) => {
    set({groupListReceipt});
  },
  setCurrentTypeReceipt: (currentTypeReceipt: TypeReceipt) => {
    set({currentTypeReceipt});
  },
  setCurrentStatusRequestReceipt: (currentRequestStatus: TYPE_REQUEST_FLOW) => {
    set({currentRequestStatus});
  },
  setGroupPageReceipt: (groupPageReceipt: GroupedPageReceipt) => {
    set({groupPageReceipt});
  },
  setGroupToTalCountReceipt: (
    groupToTalCountReceipt: GrouptTotalCountReceipt,
  ) => {
    set({groupToTalCountReceipt});
  },
  setQueryFilterReceipt: (queryFilterReceipt: string) => {
    set({queryFilterReceipt});
  },
  setListTypeReceipt: (listTypeReceipt: {label: string; value: string}[]) => {
    set({listTypeReceipt});
  },
}));
