import {StyleSheet, TouchableOpacity, View} from 'react-native';
import {Font} from '../../../../../../../constants';
import {ReleaseReceipt} from '../../helper';
import {CommonUtils, DateUtils} from '../../../../../../../utils';
import {useState} from 'react';
import {useReceiptServices} from '../../../../../../../hooks/apiHooks/useAPI';
import ModalFullScreen from '../../../../../../components/ModalFullScreen';
import WebViewScreen from '../../../../../../components/ViewWebview';
import Toast from 'react-native-toast-message';
import {useTranslation} from 'react-i18next';
import TextCM from '../../../../../../components/Text';

type Props = {
  item: ReleaseReceipt;
};
const ExpandIssueReceipt = ({item}: Props) => {
  const {t} = useTranslation();
  const [urlWebview, setUrlWebview] = useState('');
  const [openModal, setOpenModal] = useState(false);

  const RecieptService = useReceiptServices();
  const viewFile = async () => {
    const formData = new FormData();
    formData.append('keyName', item.keyName);
    formData.append('bucketName', item.bucketName);
    formData.append('beanName', item.beanName);
    const data = await RecieptService.viewFile(formData);
    if (data && data.code == 1) {
      setUrlWebview(data.message);
      setOpenModal(true);
    } else {
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    }
  };
  return (
    <View style={styles.expandedDetails}>
      {/* <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>Loại biên lai</TextCM>
        <View style={{flex: 1}}>
          <TextCM style={styles.detailValue}>{'Biên lai C20'}</TextCM>
        </View>
      </View> */}

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>Biên lai phát hành</TextCM>
        <TouchableOpacity style={{flex: 1}} onPress={viewFile}>
          <TextCM
            style={[
              styles.detailValue,
              {textDecorationLine: 'underline', color: '#366AE2'},
            ]}>
            {item.fileName || '---'}
          </TextCM>
        </TouchableOpacity>
      </View>

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>Định dạng</TextCM>
        <View style={{flex: 1}}>
          <TextCM style={styles.detailValue}>
            {item?.fileName?.split('.')?.slice(-1)?.[0] || '---'}
          </TextCM>
        </View>
      </View>

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>Dung lượng</TextCM>
        <View style={{flex: 1}}>
          <TextCM style={styles.detailValue}>
            {CommonUtils.getSize(item?.documentSize) || '---'}
          </TextCM>
        </View>
      </View>

      <View style={styles.detailRow}>
        <TextCM style={styles.detailLabel}>Phát hành</TextCM>
        <View style={{flex: 1}}>
          <TextCM style={styles.detailValue}>
            {DateUtils.convertDateToDDMMYYYY_H_M(item.createdDate)}
          </TextCM>
        </View>
      </View>

      <ModalFullScreen
        isVisible={openModal}
        children={
          <WebViewScreen
            name="File"
            onClose={() => setOpenModal(false)}
            url={urlWebview}
          />
        }
      />
    </View>
  );
};
export default ExpandIssueReceipt;

const styles = StyleSheet.create({
  expandedDetails: {
    backgroundColor: '#FFFFFF',
    borderRadius: 6,
    padding: 12,
    marginVertical: 8,
  },
  detailRow: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 8,
    columnGap: 12,
  },
  detailLabel: {
    fontSize: 12,
    fontFamily: Font.InterSemiBold600,
    color: '#00204D',
    width: 115,
  },
  detailValue: {
    fontSize: 12,
    fontFamily: Font.InterRegular400,
    color: '#00204DE5',
  },
  userInfo: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  avatar: {
    width: 24,
    height: 24,
    borderRadius: 12,
    marginRight: 8,
  },
  email: {
    fontSize: 12,
    color: '#6B7280',
  },
});
